-- Check medical_history for recipient-related data
SELECT * FROM medical_history WHERE contrib_med_registry IN (
    SELECT recip_ref_reg FROM transplant_matching LIMIT 5
);

-- Check if adm_rev_registry matches match_comp_registry directly
SELECT COUNT(*) FROM administrative_and_review ar 
JOIN compatibility_metrics cm ON ar.adm_rev_registry = cm.match_comp_registry;
